{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is low (≤0.33) and historical price trend shows mean reversion.",
    "Increase forecast sensitivity to recent price spikes (last 3-5 days) when sentiment is neutral or positive (≥0.33).",
    "Apply a lag correction: if true outcome is higher than forecast by >5% and sentiment is low, reduce next forecast by 2-3% to avoid overshoot.",
    "When sentiment is consistently low and price is trending upward, apply a mean-reversion bias: forecast = historical 18-day average + 10% of recent volatility.",
    "For horizon >15 days, reduce forecast growth rate by 15-20% if sentiment is negative or sentiment history shows persistent negativity."
  ]
}
